  %result = "nv_tensor_ir.contraction"(%a, %b) <{
    indexing_maps = [affine_map<(d0, d1, d2) -> (d0 + d1, d2)>,
                     affine_map<(d0, d1, d2) -> (d2, d1)>,
                     affine_map<(d0, d1, d2) -> (d0, d1)>]
  }> : (tensor<2x5xf32>, tensor<5x7xf32>) -> tensor<2x7xf32>
