  %result = "nv_tensor_ir.contraction"(%a, %b) <{
    indexing_maps = [affine_map<(d0, d1, d2, d3) -> (d0, d1, d3)>,
                     affine_map<(d0, d1, d2, d3) -> (d0, d3, d2)>,
                     affine_map<(d0, d1, d2, d3) -> (d0, d1, d2)>]
  }> : (tensor<2x3x5xf32>, tensor<4x5x7xf32>) -> tensor<2x3x7xf32>
