        Case{"((1,2),(?{div=4},8),32)", 2, 2, "()"}, Case{"4", 0, 1, "(4)"},
        Case{"(2,3)", 0, 8, "(2,3)"}, Case{"(3,1)", 0, 8, "(3,1)"},
        Case{"(2,3)", -1, 1, "error_t"}, Case{"(3,1)", -1, 1, "error_t"}}) {
